(40911, 'Psalms 87:5', 'Psalms', 87, 5, 'د صهیون په هکله داسې به ویل کیږي: «هغوی ټول به حق د هغه ښار د تابعیت ولري خدای تعالی به ټینګ وساتي دا ښار»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms87_verse_5.mp3', '', 1761754199, 1761754199),
(40912, 'Psalms 87:6', 'Psalms', 87, 6, 'څښتن به ثبت کړي د قومونو لست هغوی ټول به کړي حساب د صهیون په اوسېدونکو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms87_verse_6.mp3', '', 1761754199, 1761754199),
(40913, 'Psalms 87:7', 'Psalms', 87, 7, 'سندرغاړي او اتڼ کوونکي به دا وایي: «دی صهیون زما اصلي ځای»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms87_verse_7.mp3', '', 1761754199, 1761754199),
(40914, 'Ezekiel 23:1', 'Ezekiel', 23, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_1.mp3', '', 1761754199, 1761754199),
(40915, 'Ezekiel 23:2', 'Ezekiel', 23, 2, '«ای فاني انسانه، یوه مور وه چې دوه لورګانې یې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_2.mp3', '', 1761754199, 1761754199),
(40916, 'Ezekiel 23:3', 'Ezekiel', 23, 3, 'کله چې هغوی ځوانې وې او په مصر کې اوسېدلې، هغوی خلک پرېښودل چې د دوی د سینو سره لوبې وکړي، په دې ډول یې خپل پېغلتوب له لاسه ورکړ او بدلمنې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_3.mp3', '', 1761754199, 1761754199),
(40917, 'Ezekiel 23:4', 'Ezekiel', 23, 4, 'د مشرې نوم یې اهوله وه چې د سامرې معنی ورکوي او د کشرې نوم یې اهولیبه وه چې د اورشلیم معنی ورکوي. ما د هغو دواړو سره واده وکړ او د هغوی نه مې زامن او لورګانې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_4.mp3', '', 1761754199, 1761754199),
(40918, 'Ezekiel 23:5', 'Ezekiel', 23, 5, 'که څه هم اهوله زما ښځه وه، خو هغې خپل بدلمنتوب کاوه او شوق یې درلود چې د خپلو عاشقانو یعنې آشوري جنګیالیانو سره شهواني اړیکې ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_5.mp3', '', 1761754199, 1761754199),
(40919, 'Ezekiel 23:6', 'Ezekiel', 23, 6, 'هغوی عسکر وو او بانجاني کالي یې اغوستي وو، والیان او لوړ‌رتبه مامورین وو، دا ټول ښکلي ځوانان او اس سپاره وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_6.mp3', '', 1761754199, 1761754199),
(40920, 'Ezekiel 23:7', 'Ezekiel', 23, 7, 'هغې د آشوريانو سره بدلمني کوله چې ټول یې منصبداران وو او د هغې شهوت پرستي د دې سبب شوه چې خپل ځان د آشوریانو بتانو ته په عبادت کولو سره ناپاکه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_7.mp3', '', 1761754199, 1761754199),
(40921, 'Ezekiel 23:8', 'Ezekiel', 23, 8, 'هغې چې کوم بدلمنتوب په مصر کې پیل کړی ؤ، د هغې نه یې لاس وانخیست. هلته یې خپل پېغلتوب له لاسه ورکړی ؤ. د ځوانۍ د وخت نه به خلکو د هغې د سینو سره لوبې کولې او د هغې سره یې شهواني اړیکې لرلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_8.mp3', '', 1761754199, 1761754199),
(40922, 'Ezekiel 23:9', 'Ezekiel', 23, 9, 'نو هغه مې خپل آشوري عاشقانو ته چې د هغوی سره یې زیاتې شهواني اړیکې غوښتلې، ورتسلیمه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_9.mp3', '', 1761754199, 1761754199),
(40923, 'Ezekiel 23:10', 'Ezekiel', 23, 10, 'هغوی هغه لوڅه کړه، د هغې زامن او لورګانې یې ونیولې او هغه یې په توره باندې ووژله. په هرځای کې به ښځو د هغې د سرنوشت او سزا په هکله خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_10.mp3', '', 1761754199, 1761754199),
(40924, 'Ezekiel 23:11', 'Ezekiel', 23, 11, 'که څه هم د هغې خور اهولیبه دا هرڅه ولیدل، خو بیاهم هغه په خپل شهوت او بدلمنتوب کې د خپلې خور اهولې نه هم زیاته فاسده شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_11.mp3', '', 1761754199, 1761754199),
(40925, 'Ezekiel 23:12', 'Ezekiel', 23, 12, 'هغې هم د آشوریانو په هغو والیانو، لوړ‌رتبه مامورینو او عسکرو چې ښکلي کالي یې اغوستي وو او په اسونو سپاره وو، غوښتل چې د هغوی سره شهواني اړیکې ولري. دا ټول زړه وړونکي ځوانان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_12.mp3', '', 1761754199, 1761754199),
(40926, 'Ezekiel 23:13', 'Ezekiel', 23, 13, 'ما ولیدل چې هغه بیخي بد‌اخلاقه شوه او دوهمه خور یې هم د اولنۍ خور لاره غوره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_13.mp3', '', 1761754199, 1761754199),
(40927, 'Ezekiel 23:16', 'Ezekiel', 23, 16, 'څنګه چې هغې دا ولیدل، نو هغې غوښتل چې د هغوی سره شهواني اړیکې ولري او هغوی پسې یې قاصدان بابل ته ولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_16.mp3', '', 1761754199, 1761754199),
(40928, 'Ezekiel 23:17', 'Ezekiel', 23, 17, 'بابلیان راغلل او د هغې سره یې زنا وکړه. هغه یې په خپل شهوت ناپاکه کړه او وروسته هغه ورڅخه بېزاره شوه او د هغوی نه یې مخ واړاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_17.mp3', '', 1761754199, 1761754199),
(40929, 'Ezekiel 23:18', 'Ezekiel', 23, 18, 'هغې په ښکاره ځان لوڅاوه او بدلمنتوب یې کاوه. نو زه د هغې نه دومره بېزاره شوم چې خپل مخ مې ترې واړاوه، لکه څنګه چې د هغې د خور نه بېزاره شوی وم او خپل مخ مې ترې اړولی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_18.mp3', '', 1761754199, 1761754199),
(40930, 'Ezekiel 23:19', 'Ezekiel', 23, 19, 'هغه د بل هر وخت نه هم زیاته بدلمنه شوه او داسې بدلمنتوب یې کاوه، لکه څنګه چې هغې د خپلې ځوانۍ د دوران په ياد په مصر کې کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_19.mp3', '', 1761754199, 1761754199),
(40931, 'Ezekiel 23:20', 'Ezekiel', 23, 20, 'هغې د هغو شهوت پرسته خلکو هوس کاوه چې د هغوی تناسلي الې د خره او انزال یې د اس په شان زیات ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_20.mp3', '', 1761754199, 1761754199),
(40932, 'Ezekiel 23:21', 'Ezekiel', 23, 21, 'نو ای اهولیبې، تا غوښتل چې خپله هغه بد‌اخلاقي تکرار کړې چې په پېغلتوب کې دې په مصر کې کاوه یعنې چېرته چې سړیو ستا د سینو سره لوبې کولې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_21.mp3', '', 1761754199, 1761754199),
(40933, 'Ezekiel 23:22', 'Ezekiel', 23, 22, '«نو ای اهولیبې، زه څښتن تعالی تاته داسې وایم: ‹ګوره، ستا په وړاندې به هغه عاشقان راپورته کړم چې ورڅخه بېزاره شوې یې او مخ دې ورڅخه اړولی دی. هغوی به د هرې خوا نه په تا باندې راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_22.mp3', '', 1761754199, 1761754199),
(40934, 'Ezekiel 23:23', 'Ezekiel', 23, 23, 'زه به بابلیان، کلدانیان او د فقود، شوع او قوع سړي او ورسره ټول آشوریان راولم. دا به ټول ښکلي ځوانان وي، دا به والیان، لوړ‌رتبه مامورین او منصبداران وي، هغوی به ټول په اسونو سپاره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_23.mp3', '', 1761754199, 1761754199),
(40935, 'Ezekiel 23:24', 'Ezekiel', 23, 24, 'هغوی به د یو لوی لښکر، جنګي او د سامان وړلو ګاډیو سره د شمال له خوا په تا باندې حمله وکړي. هغوی به تا کلابند کړي او د وړو او لویو سپرونو او د زغرو د خولیو په وسیله به د خپل ځان ساتنه وکړي. زه به تا هغوی ته په لاس ورکړم او تاته به د خپل قانون له مخې سزا درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_24.mp3', '', 1761754199, 1761754199),
(40936, 'Ezekiel 23:25', 'Ezekiel', 23, 25, 'په دې خاطر چې زما غیرت راپارېدلی دی، نو زه به هغوی پرېږدم چې ستا سره د ډېر قهر نه کار واخلي. هغوی به ستا پوزه او غوږونه پرې کړي او ستا اولادونه به ووژني. هو، هغوی به ستا زامن او لورګانې بوځي او هغوی به ژوندي وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_25.mp3', '', 1761754199, 1761754199),
(40937, 'Ezekiel 23:26', 'Ezekiel', 23, 26, 'هغوی به ستا نه کالي وباسي او ستا ښکلي زېورات به درڅخه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_26.mp3', '', 1761754199, 1761754199),
(40938, 'Ezekiel 23:27', 'Ezekiel', 23, 27, 'نو زه به ستا شهوت پرستي او بدلمنتوب چې د مصر نه دې له ځان سره راوړی دی، پای ته ورسوم. ته به نور بتانو ته نه ګورې او نه به د مصر په هکله فکر کوې.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_27.mp3', '', 1761754199, 1761754199),
(40939, 'Ezekiel 23:28', 'Ezekiel', 23, 28, 'زه څښتن تعالی داسې وایم: ‹زه به تا هغو خلکو ته په لاس ورکړم چې ورڅخه کرکه کوې، ورڅخه بېزاره شوې او د هغوی نه دې مخ واړاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_28.mp3', '', 1761754199, 1761754199),
(40940, 'Ezekiel 23:29', 'Ezekiel', 23, 29, 'په دې خاطر چې هغوی ستا نه کرکه کوي، نو هغوی به ستا نه هغه ټول شیان واخلي چې د هغو دپاره دې زحمت ویستلی دی او هغوی به د یوې بدلمنې په شان تا لوڅه پرېږدي. دا هرڅه ستا شهوت او ستا بدلمنتوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_29.mp3', '', 1761754199, 1761754199),
(40941, 'Ezekiel 23:30', 'Ezekiel', 23, 30, 'په تا باندې راوستلي دي. ته د ټولو قومونو دپاره بدلمنه یې او د هغوی په بتانو باندې دې خپل ځان ناپاکه کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_30.mp3', '', 1761754199, 1761754199),
(40942, 'Ezekiel 23:31', 'Ezekiel', 23, 31, 'ته د خپلې خور په لاره باندې روانه شوې، نو زه به د سزا هماغه پیاله تاته درکړم چې ویې څښې.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_31.mp3', '', 1761754199, 1761754199),
(40943, 'Ezekiel 23:32', 'Ezekiel', 23, 32, '«څښتن تعالی داسې وایي: ‹ته به وڅښې د خپلې خور له پیالې هغه ده غټه او ژوره هرڅوک به تا پسې کوي خندا او وهي ملنډې به په تا باندې ځکه چې ډکه ده هغه پیاله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_32.mp3', '', 1761754199, 1761754199),
(40944, 'Ezekiel 23:33', 'Ezekiel', 23, 33, 'هغه به تا کاندي غمجن او نشه د وحشت او نابودۍ هغه پیاله ستا د خور سامرې پیاله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_33.mp3', '', 1761754199, 1761754199),
(40945, 'Ezekiel 23:34', 'Ezekiel', 23, 34, 'هغه به وڅښې او خالي به یې کړې وبه ژوې د هغې ماتې ټوټې او پرې به کړې خپله سینه› ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_34.mp3', '', 1761754199, 1761754199),
(40946, 'Ezekiel 23:35', 'Ezekiel', 23, 35, 'نو څښتن تعالی داسې وایي: ‹په دې خاطر چې تا زه هېر کړی یم او ماته دې شا اړولې ده، نو ته به د خپلې شهوت پرستۍ او خپل بدلمنتوب په سبب کړېږې.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_35.mp3', '', 1761754199, 1761754199),
(40947, 'Ezekiel 23:36', 'Ezekiel', 23, 36, 'څښتن ماته وویل: «ای فاني انسانه، اهوله او اهولیبه محاکمه کړه. هغوی د هغو کرکې وړ کارونو په سبب چې کړي یې دي، ملامته کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_36.mp3', '', 1761754199, 1761754199),
(40948, 'Ezekiel 23:37', 'Ezekiel', 23, 37, 'هغوی زنا کړې ده او لاسونه یې د خلکو په وینو باندې سره دي. هغوی د بتانو په عبادت کولو سره زما په وړاندې زنا کړې ده. هغه زامن یې قتل کړي دي چې ماته یې زېږولي وو او هغوی یې د خوړو په توګه بتانو ته قرباني کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_37.mp3', '', 1761754199, 1761754199),
(40949, 'Ezekiel 23:38', 'Ezekiel', 23, 38, 'هغوی نور کارونه هم کړي دي. په هماغه وخت کې هغوی زما د عبادت ځای ناپاکه کړ او د سبت د ورځې بې‌عزتي یې وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_38.mp3', '', 1761754199, 1761754199),
(40950, 'Ezekiel 23:39', 'Ezekiel', 23, 39, 'په هماغه ورځ چې هغوی زما اولادونه خپلو بتانو ته د قربانۍ دپاره ووژل، هغوی زما عبادتځای ته راغلل او د هغه سپکاوی یې وکړ. دا هغه څه دي چې هغوی زما په کور کې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_39.mp3', '', 1761754199, 1761754199),
(40951, 'Ezekiel 23:40', 'Ezekiel', 23, 40, 'حتی هغوی استازي ولېږل چې د لېرې لېرې ځایونو نه سړي راوبولي او کله چې هغوی راغلل، دواړو خویندو خپل ځانونه ووینځل، سترګې یې تورې کړلې او ګاڼې یې واچولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_40.mp3', '', 1761754199, 1761754199),
(40952, 'Ezekiel 23:41', 'Ezekiel', 23, 41, 'هغوی په ښایسته کوچونو باندې کښېناستلې او د کوچونو په مخکې یو مېز تیار شوی ؤ چې په مېز باندې خوشبویي او د زیتونو تېل چې ما ورته ورکړي وو، ایښي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_41.mp3', '', 1761754199, 1761754199),
(40953, 'Ezekiel 23:42', 'Ezekiel', 23, 42, 'د هغوی شاوخوا نه د عیاشو خلکو د ډلې اواز اورېدل کېده، دا د هغو سړیو ډله وه چې د دښتې نه یې راوستلي وو. هغوی ښځو ته بنګړي په لاس کړل او ښکلي تاجونه یې ورته په سرونو باندې کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_42.mp3', '', 1761754199, 1761754199),
(40954, 'Ezekiel 23:43', 'Ezekiel', 23, 43, 'نو ما د خپل ځان سره وویل سره له دې چې هغه ښځې د زنا کولو نه ستړې شوې دي، خو بیاهم هغه سړي ورڅخه د بدلمنې په توګه کار اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_43.mp3', '', 1761754199, 1761754199),
(40955, 'Ezekiel 23:44', 'Ezekiel', 23, 44, 'هغوی دې دوه بدلمنو یعنې اهوله او اهولیبه ته ورغلل چې شهوت پرسته ښځې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_44.mp3', '', 1761754199, 1761754199),
(40956, 'Ezekiel 23:45', 'Ezekiel', 23, 45, 'خو نېک خلک به هغوی د زناکارۍ او قتلونو له امله محکوم کړي، ځکه چې هغوی زنا کوي او لاسونه یې په وینو باندې سره دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_45.mp3', '', 1761754199, 1761754199),
(40957, 'Ezekiel 23:46', 'Ezekiel', 23, 46, 'نو څښتن تعالی داسې وایي: یو لښکر راولئ چې هغوی سخت ووېروي او لوټ یې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_46.mp3', '', 1761754199, 1761754199),
(40958, 'Ezekiel 23:47', 'Ezekiel', 23, 47, 'هغه ډله به هغوی سنګسار کړي او په خپلو تورو باندې به د هغوی بدنونه ټوټې ټوټې کړي. د هغوی زامن او لورګانې به ووژني او کورونه به یې وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_47.mp3', '', 1761754199, 1761754199),
(40959, 'Ezekiel 23:48', 'Ezekiel', 23, 48, 'نو زه به ټول وطن کې شهوت پرستي پای ته ورسوم او دا به ټولو ښځو ته یو خبرداری وي چې د هغوی په شان شهوت پرستي ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_48.mp3', '', 1761754199, 1761754199),
(40960, 'Ezekiel 23:49', 'Ezekiel', 23, 49, 'ای دواړو خویندو، زه به تاسو ته ستاسو د شهوت پرستۍ او بتانو ته د عبادت کولو د ګناه په خاطر سزا درکړم. بیا به تاسو پوه شئ چې زه څښتن تعالی یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel23_verse_49.mp3', '', 1761754199, 1761754199),
(40961, 'Numbers 3:1', 'Numbers', 3, 1, 'دا د موسی او هارون د کورنۍ د هغه وخت کیسه ده کله چې څښتن د موسی سره د سینا په غره کې خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_1.mp3', '', 1761754199, 1761754199),
(40962, 'Numbers 3:2', 'Numbers', 3, 2, 'هارون څلور زامن درلودل: ناداب چې مشر ؤ، ابیهو، العازار او ایتامار.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_2.mp3', '', 1761754199, 1761754199),
(40963, 'Numbers 3:3', 'Numbers', 3, 3, 'هغوی مسح کړای شول او د کاهنانو په توګه وټاکل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_3.mp3', '', 1761754199, 1761754199),
(40964, 'Numbers 3:4', 'Numbers', 3, 4, 'خو ناداب او ابیهو د څښتن په حضور کې په داسې وخت کې مړه شول کله چې هغوی د سینا په دښته کې څښتن ته ناپاکه اور وړاندې کاوه. هغوی اولادونه نه درلودل، نو العازار او ایتامار د هارون د ژوندانه په دوران کې د کاهنانو په توګه خدمت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_4.mp3', '', 1761754199, 1761754199),
(40965, 'Numbers 3:5', 'Numbers', 3, 5, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_5.mp3', '', 1761754199, 1761754199),
(40966, 'Numbers 3:6', 'Numbers', 3, 6, '«د لاویانو قبیله راوله او د هارون کاهن د خدمتګارانو په توګه یې وټاکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_6.mp3', '', 1761754199, 1761754199),
(40967, 'Numbers 3:7', 'Numbers', 3, 7, 'دوی به په سپېڅلې خېمه کې کار کوي او د هارون او ټول قوم دپاره به دندې سرته رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_7.mp3', '', 1761754199, 1761754199),
(40968, 'Numbers 3:8', 'Numbers', 3, 8, 'هغوی به د سپېڅلې خېمې د ټول سامان مسوولیت په غاړه واخلي او د نورو اسراییلیانو دپاره به کار کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_8.mp3', '', 1761754199, 1761754199),
(40969, 'Numbers 3:9', 'Numbers', 3, 9, 'د لاویانو مسوولیت دا دی چې د هارون او د هغه د زامنو خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_9.mp3', '', 1761754199, 1761754199),
(40970, 'Numbers 3:10', 'Numbers', 3, 10, 'هارون او د هغه زامن د کاهنانو په توګه د خدمت دپاره وټاکه. که بل هرڅوک سپېڅلي ځای ته ورنژدې شي، باید ووژل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_10.mp3', '', 1761754199, 1761754199),
(40971, 'Numbers 3:11', 'Numbers', 3, 11, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_11.mp3', '', 1761754199, 1761754199),
(40972, 'Numbers 3:14', 'Numbers', 3, 14, 'څښتن موسی ته د سینا په دښته کې وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_14.mp3', '', 1761754199, 1761754199),
(40973, 'Numbers 3:15', 'Numbers', 3, 15, '«لاویان کورنۍ په کورنۍ او طایفه په طایفه وشمېره. هر نارینه چې عمر یې یوه میاشت یا زیات وي وشمېره.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_15.mp3', '', 1761754199, 1761754199),
(40974, 'Numbers 3:16', 'Numbers', 3, 16, 'نو څنګه چې څښتن ورته امر کړی ؤ، موسی هغوی وشمېرل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_16.mp3', '', 1761754199, 1761754199),
(40975, 'Numbers 3:21', 'Numbers', 3, 21, 'لبنیان او شمعیان د جرشونیانو طایفې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_21.mp3', '', 1761754199, 1761754199),
(40976, 'Numbers 3:22', 'Numbers', 3, 22, 'د هغو نارینه جرشونیانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ او وشمېرل شول، ۷۵۰۰ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_22.mp3', '', 1761754199, 1761754199),
(40977, 'Numbers 3:23', 'Numbers', 3, 23, 'دغو طایفو د سپېڅلې خېمې شاته یعنې لوېدیځ خواته خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_23.mp3', '', 1761754199, 1761754199),
(40978, 'Numbers 3:24', 'Numbers', 3, 24, 'د جرشونیانو د کورنیو مشر د لایل زوی الیاساف ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_24.mp3', '', 1761754199, 1761754199),
(40979, 'Numbers 3:25', 'Numbers', 3, 25, 'په سپېڅلې خېمه کې جرشونیان د دغو شیانو د ساتنې مسوولان وو: د خېمې، د هغې د پوښونو، د خېمې د دروازې د پردې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_25.mp3', '', 1761754199, 1761754199),
(40980, 'Numbers 3:26', 'Numbers', 3, 26, 'د حوېلۍ د پردو، د هغې حوېلۍ د دروازې د پردې چې د سپېڅلې خېمې او قربانۍ د ځای ګردچاپېره ده او د هغو د رسۍ ګانو. هغوی د دې ټول سامان او په هغه پورې د اړونده کارونو مسوولیت په غاړه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_26.mp3', '', 1761754199, 1761754199),
(40981, 'Numbers 3:27', 'Numbers', 3, 27, 'عمرامیان، یصهاریان، حبرونیان او عزییلیان د قهاتیانو طایفې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_27.mp3', '', 1761754199, 1761754199),
(40982, 'Numbers 3:28', 'Numbers', 3, 28, 'د هغو نارینه قهاتیانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ ۸۶۰۰ تنه وو. قهاتیانو د سپېڅلي ځای د ساتنې مسوولیت په غاړه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_28.mp3', '', 1761754199, 1761754199),
(40983, 'Numbers 3:29', 'Numbers', 3, 29, 'دغو طایفو د سپېڅلې خېمې جنوب خواته خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_29.mp3', '', 1761754199, 1761754199),
(40984, 'Numbers 3:30', 'Numbers', 3, 30, 'د قهاتیانو د طایفو د کورنیو مشر د عزییل زوی الیصافان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_30.mp3', '', 1761754199, 1761754199),
(40985, 'Numbers 3:31', 'Numbers', 3, 31, 'د دغو شیانو مسوولیت د هغوی په غاړه ؤ: د لوظ صندوق، مېز، څراغدان، د قربانۍ د ځایونو، هغه لوښي چې کاهنانو په سپېڅلي ځای کې ورڅخه کار اخیست او د ډېر سپېڅلي ځای د دروازې پرده. هغوی د دې ټول سامان او په هغه پورې د اړونده کارونو مسوولیت په غاړه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_31.mp3', '', 1761754199, 1761754199),
(40986, 'Numbers 3:32', 'Numbers', 3, 32, 'د لاویانو د مشرانو رییس د هارون کاهن زوی العازار ؤ. هغه په هغو خلکو باندې مقرر شوی ؤ چې د سپېڅلي ځای د ساتنې مسوولان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_32.mp3', '', 1761754199, 1761754199),
(40987, 'Numbers 3:33', 'Numbers', 3, 33, 'محلیان او موشیان د مراریانو طایفې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_33.mp3', '', 1761754199, 1761754199),
(40988, 'Numbers 3:34', 'Numbers', 3, 34, 'د هغو نارینه مراریانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ او وشمېرل شول، ۶۲۰۰ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_34.mp3', '', 1761754199, 1761754199),
(40989, 'Numbers 3:35', 'Numbers', 3, 35, 'د مراریانو د طایفو د کورنیو مشر د ابیحایل زوی صوری ییل ؤ. هغوی د سپېڅلې خېمې شمال خواته خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_35.mp3', '', 1761754199, 1761754199),
(40990, 'Numbers 3:36', 'Numbers', 3, 36, 'مراریان د دې دپاره ټاکل شوي وو چې د سپېڅلې خېمې په چوکاټونو، د هغې د اړمونو، ستنو، پایو او د هغې د ټول سامان ساتنه وکړي. هغوی د دې ټول سامان او په هغه پورې د اړونده کارونو مسوولیت په غاړه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_36.mp3', '', 1761754199, 1761754199),
(40991, 'Numbers 3:37', 'Numbers', 3, 37, 'همدارنګه هغوی د ستنو، پایو، مېخونو او د هغو رسۍ ګانو مسوولیت په غاړه درلود چې د شاوخوا حوېلۍ دپاره وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_37.mp3', '', 1761754199, 1761754199),
(40992, 'Numbers 3:38', 'Numbers', 3, 38, 'موسی او هارون او د هارون زامنو د سپېڅلې خېمې لمرخاته خواته یعنې د سپېڅلې خېمې په مخکې خېمې ودرولې. هغوی د هغو کارونو د سرته رسولو مسوولیت په غاړه درلود چې د اسراییلو د قوم دپاره په سپېڅلي ځای کې تر سره کېدل. بل هرڅوک به چې سپېڅلي ځای ته ورنژدې کېده، هغه به وژل کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_38.mp3', '', 1761754199, 1761754199),
(40993, 'Numbers 3:39', 'Numbers', 3, 39, 'د هغو ټولو نارینه لاویانو شمېر چې عمر یې یوه میاشت یا زیات ؤ او موسی او هارون د څښتن په امر طایفه په طایفه وشمېرل، ټول ۲۲۰۰۰ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_39.mp3', '', 1761754199, 1761754199),
(40994, 'Numbers 3:40', 'Numbers', 3, 40, 'څښتن موسی ته وویل: «د اسراییلو ټول مشران زامن چې عمر یې یوه میاشت یا زیات وي وشمېره او د هغوی د نومونو یو لست تیار کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_40.mp3', '', 1761754199, 1761754199),
(40995, 'Numbers 3:41', 'Numbers', 3, 41, 'د اسراییلو د ټولو مشرانو زامنو په ځای زما دپاره لاویان واخله او د هغوی د ټولو لومړنیو زېږېدلو حیواناتو په ځای زما دپاره د لاویانو حیوانات واخله. زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_41.mp3', '', 1761754199, 1761754199),
(40996, 'Numbers 3:42', 'Numbers', 3, 42, 'نو څنګه چې څښتن موسی ته امر کړی ؤ، هغه د اسراییلو ټول مشران زامن وشمېرل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_42.mp3', '', 1761754199, 1761754199),
(40997, 'Numbers 3:43', 'Numbers', 3, 43, 'د نارینه مشرانو ټول شمېر چې عمر یې یوه میاشت یا زیات ؤ او د هر یو نوم په لست کې لیکل شوی ؤ، ۲۲۲۷۳ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_43.mp3', '', 1761754199, 1761754199),
(40998, 'Numbers 3:44', 'Numbers', 3, 44, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_44.mp3', '', 1761754199, 1761754199),
(40999, 'Numbers 3:45', 'Numbers', 3, 45, '«اوس د اسراییلو د ټولو مشرانو زامنو په ځای لاویان وقف کړه او د لاویانو حیوانات د هغوی د حیواناتو په ځای وقف کړه. لاویان دې زما شي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_45.mp3', '', 1761754199, 1761754199),
(41000, 'Numbers 3:46', 'Numbers', 3, 46, 'په دې خاطر چې د اسراییلو مشران زامن د لاویانو په پرتله ۲۷۳ تنه زیات دي، نو ته باید اضافي زامن بېرته په بیه واخلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_46.mp3', '', 1761754199, 1761754199),
