(41002, 'Numbers 3:48', 'Numbers', 3, 48, 'او هغه هارون او د هغه زامنو ته ورکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_48.mp3', '', 1761754199, 1761754199),
(41003, 'Numbers 3:49', 'Numbers', 3, 49, 'موسی د ۲۷۳ اضافي مشرانو زامنو څخه سپین زر راټول کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_49.mp3', '', 1761754199, 1761754199),
(41004, 'Numbers 3:50', 'Numbers', 3, 50, 'چې د هغو وزن د سپېڅلي ځای د معیار له مخې ۱۳۶۵ سکې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_50.mp3', '', 1761754199, 1761754199),
(41005, 'Numbers 3:51', 'Numbers', 3, 51, 'هغه یې د څښتن د حکم سره سم هارون او د هغه زامنو ته ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers3_verse_51.mp3', '', 1761754199, 1761754199),
(41006, 'Zechariah 14:1', 'Zechariah', 14, 1, 'ګورئ، د مالِک خُدائ ورځ راروانه ده چې ستاسو مال به بلکل ستاسو په وړاندې لوټ کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_1.mp3', '', 1761754199, 1761754199),
(41007, 'Zechariah 14:2', 'Zechariah', 14, 2, 'زۀ به ټول قومونه راغونډ کړم چې د يروشلم خلاف جنګ وکړى، ښار به محاصره شى، کورونه به لوټ شى او ښځې به په زور بې‌عزته شى. نيم ښار به جلاوطن شى، خو نور پاتې خلق به د ښار نه بونۀ تلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_2.mp3', '', 1761754199, 1761754199),
(41008, 'Zechariah 14:3', 'Zechariah', 14, 3, 'بيا به مالِک خُدائ لاړ شى او د هغه قومونو خلاف به داسې جنګ وکړى، لکه څنګه چې هغۀ پخوا جنګ کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_3.mp3', '', 1761754199, 1761754199),
(41009, 'Zechariah 14:4', 'Zechariah', 14, 4, 'په هغه ورځ به د هغۀ پښې د زيتُونو په غر د يروشلم مشرق طرف ته ودريږى. او د زيتُونو غر به د مشرق نه تر مغرب پورې په مينځ نيم شى، يوه لويه وادى به جوړه شى، دا غر به نيم د شمال طرف ته او نيم د جنوب طرف ته وښويږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_4.mp3', '', 1761754199, 1761754199),
(41010, 'Zechariah 14:5', 'Zechariah', 14, 5, 'بيا به تاسو زما د غرۀ په وادۍ کښې وتښتئ، ځکه دا به تر آضل پورې رسېدلې وى. تاسو به داسې وتښتئ لکه څنګه چې تاسو د يهوداه د بادشاه عُزياه په ورځو کښې د زلزلې نه وتښتېدلئ. بيا مالِک خُدائ زما خُدائ پاک به راشى، او ټولې پاکې فرښتې به هغۀ سره راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah14_verse_5.mp3', '', 1761754199, 1761754199);